"""Independent read-only raw V21 review; no producer checker or FE import."""
import csv, hashlib, json, pathlib, subprocess, time
import numpy as np
R=pathlib.Path('/home/fenics/Projects/NN-Lab-V2'); T=R/'docs/task042extra_feinn_5nm/outcomes/records'
start=time.monotonic(); checked={}
def sha(p):
    h=hashlib.sha256()
    with p.open('rb') as f:
        for b in iter(lambda:f.read(4*1024*1024),b''):h.update(b)
    return h.hexdigest()
def bind(x):
    p=pathlib.Path(x['path']);p=p if p.is_absolute() else R/p
    if str(p) not in checked:checked[str(p)]=sha(p)
    assert checked[str(p)]==x['sha256'],str(p)
    return p
def walk(x):
    if isinstance(x,dict):
        if isinstance(x.get('path'),str) and isinstance(x.get('sha256'),str):bind(x)
        for v in x.values():walk(v)
    elif isinstance(x,list):
        for v in x:walk(v)
for p in T.glob('*_v21.json'):walk(json.loads(p.read_text()))
idx=json.loads((R/'benchmarks/artifacts/task42extra/index_v21_physical_compare_attempt1.json').read_text())
roles=json.loads(bind(idx['files']['role_indices']).read_text());walk(roles)
with np.load(bind(idx['files']['integrals'])) as z:ints={k:z[k] for k in z.files}
obs={};physics=[];schemata={}
for role,rec in roles.items():
    with np.load(bind(rec['files']['observables'])) as z:a={k:z[k] for k in z.files}
    obs[role]=a
    schemata[role]={k:dict(shape=list(v.shape),dtype=str(v.dtype)) for k,v in a.items()}
    w=a['quadrature_weights_nm3'];k0=float(a['k0']);mu=complex(a['mu_r'])
    e=a['mode_e']*a['outgoing_boundary'][:,None];h=np.cross(a['mode_k'],e)/(k0*mu)
    power=np.real(np.cross(e,h.conj()))[:,2]*np.where(a['mode_keys'][:,0]=='top',1,-1)*float(a['port_area'])/(2*float(a['incident_power']))
    power=np.maximum(power,0);assert np.max(abs(power-a['per_level_power']))<1e-12
    refl=float(sum(power[a['mode_keys'][:,0]=='top']));trans=float(sum(power[a['mode_keys'][:,0]=='bottom']))
    av=float(.5*k0*np.sum(a['cell_epsilon'].imag[:,None]*w*np.sum(abs(a['total_E'])**2,axis=2))/float(a['incident_power']))
    norms=[float(np.sqrt(np.sum(w*np.sum(abs(a[k])**2,axis=2)))/(k0 if 'curl' in k else 1)) for k in ('total_E','total_curl','scattered_E','scattered_curl')]
    assert np.allclose(norms,a['physical_field_norms'],rtol=1e-12,atol=1e-14)
    for kind in ('total','scattered'):assert np.array_equal(a[kind+'_H'],a[kind+'_curl']/(1j*k0*mu))
    physics.append(dict(role=role,R=refl,T=trans,A_volume=av,closure=abs(refl+trans+av-1),norms=norms))
counts={}
for label in ('channels','samples','regions'):
    rows=list(csv.DictReader((T/(label+'_v21.csv')).open()));counts[label]=len(rows)
    for r in rows:
        if label=='channels':
            a=obs[r['role']];key=[r[k] for k in ('side','m','n','polarization')];ids=np.flatnonzero(np.all(a['mode_keys']==key,axis=1));assert len(ids)==1;j=ids[0]
            assert float(r['reference_z_nm'])==a['mode_boundary_z'][j]
            assert float(r['power_incident_normalized'])==a['per_level_power'][j]
            for k in ('total_projection','scattered_projection','outgoing_origin','outgoing_boundary'):assert complex(float(r[k+'_real']),float(r[k+'_imag']))==a[k][j]
        elif label=='samples':
            a=obs[r['role']];j=int(r['point'])
            for v,axis in enumerate(('x','y','z')):
                assert float(r[axis+'_nm'])==a['selected_points_nm'][j,v]
                for k in ('total_E','total_H','scattered_E','scattered_H'):assert complex(float(r[k+'_'+axis+'_real']),float(r[k+'_'+axis+'_imag']))==a['selected_'+k][j,v]
        else:
            ri=['all','air','substrate','grating','notch','interface_band'].index(r['region']);qi=['total_E','total_scaled_curl','scattered_E','scattered_scaled_curl'].index(r['quantity'])
            raw=ints[r['pair']+'_q15'][ri,qi];expected=[np.sqrt(raw[0]),np.sqrt(raw[2]),np.sqrt(raw[1]),max(np.sqrt(raw[1]),1e-12),np.sqrt(raw[0])/max(np.sqrt(raw[1]),1e-12)]
            for k,v in zip(('absolute','candidate_norm','original_reference_norm','denominator','relative'),expected):assert abs(float(r[k])-v)<=1e-13*max(abs(v),1e-24)
pairs={}
for pair in ('O3_vs_E3','E3_vs_E4'):
    aa,bb=pair.split('_vs_');a,b=obs[aa],obs[bb];perm=np.array([np.flatnonzero(np.all(b['mode_keys']==key,axis=1))[0] for key in a['mode_keys']])
    modes={}
    for k in ('total_projection','scattered_projection','outgoing_origin','outgoing_boundary'):
        ref=b[k][perm];d=abs(a[k]-ref);den=np.maximum(abs(ref),1e-12);rel=d/den;j=int(np.argmax(rel))
        modes[k]=dict(worst_key=a['mode_keys'][j].tolist(),max_relative=float(rel[j]),absolute=float(d[j]),denominator=float(den[j]),reference_abs=float(abs(ref[j])),candidate=[float(a[k][j].real),float(a[k][j].imag)],reference=[float(ref[j].real),float(ref[j].imag)],over_1e3_count=int(np.sum(rel>1e-3)))
    q15,q30=ints[pair+'_q15'],ints[pair+'_q30']
    pairs[pair]=dict(fields=(np.sqrt(q15[0,:,0])/np.maximum(np.sqrt(q15[0,:,1]),1e-12)).tolist(),field_abs=np.sqrt(q15[0,:,0]).tolist(),reference_norm=np.sqrt(q15[0,:,1]).tolist(),qdrift=float(np.max(abs(q15-q30)/np.maximum(abs(q30),1e-24))),modes=modes)
rows=list(csv.DictReader((T/'mode_errors_v21.csv').open()));counts['mode_errors']=len(rows)
print('mode_error_schema',rows[0])
print('alpha_csv_schema',next(csv.DictReader((T/'alpha_recovery_modes_v21.csv').open())))
result=dict(schema='review_v21.raw_audit.v1',bindings=checked,bound_files=len(checked),physics=physics,csv_counts=counts,pairs=pairs,obs_schema=schemata,integrals_schema={k:list(v.shape) for k,v in ints.items()},roles=roles,FE_assembly_solve_factor_training=0,worker_seconds=time.monotonic()-start)
(R/'tmp/task42extra/review_v21_raw_audit.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items() if k not in ('bindings','roles','obs_schema')},indent=2))
